python3 - <<'PY'
import os, re, glob, math, time
base=os.path.expanduser("~/.local/share/copyq/copyq/items")
files=sorted(glob.glob(base+"/*/*/*/*.dat"), key=lambda p: os.path.getmtime(p))
def entropy(s):
    if not s: return 0
    from collections import Counter
    c=Counter(s); n=len(s)
    return -sum((v/n)*math.log2(v/n) for v in c.values())
def strings(b):
    out=[]
    for m in re.finditer(rb'[\x20-\x7e]{4,}', b): out.append(m.group().decode('latin1'))
    try:
        t=b.decode('utf-16-be','ignore')
        for line in re.split(r'[\x00-\x1f]+', t):
            if len(line)>=4: out.append(line)
    except: pass
    return out
def classify(s):
    s=s.strip()
    if not s or ' ' in s: return None
    if re.match(r'^(https?|ftp)://', s): return 'url'
    if re.match(r'^[\w.+-]+@[\w.-]+$', s): return 'email'
    if re.match(r'^(/[^ ]+|[A-Za-z]:\\\\)', s): return 'path'
    if re.match(r'^[0-9a-fA-F]{32,}$', s): return 'hex/blob'
    if 6<=len(s)<=80 and re.search(r'[A-Za-z]', s) and re.search(r'[0-9]', s) and entropy(s)>3.2:
        return 'token?'
    if 8<=len(s)<=80 and re.search(r'[A-Za-z]', s) and re.search(r'[^A-Za-z0-9]', s) and entropy(s)>3.0:
        return 'pass?'
    return None
print(f"всего item .dat файлов: {len(files)}")
for p in files:
    b=open(p,'rb').read()
    st=strings(b)
    classes={}
    samples=[]
    for s in st:
        c=classify(s)
        if c:
            classes[c]=classes.get(c,0)+1
            if c in ('token?','pass?') and len(samples)<4:
                samples.append(f"{c}:{s[:2]}…({len(s)})")
    ts=time.strftime('%m-%d %H:%M', time.localtime(os.path.getmtime(p)))
    if classes:
        print(f"[{ts}] {os.path.basename(p)[:12]} size={len(b)} classes={classes} samples={samples}")
